import { execSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";

const root = process.cwd();
const config = JSON.parse(
  readFileSync(path.join(root, "harness.config.json"), "utf8"),
);
const criterion = config.criteria.find((entry) => entry.id === "escape-hatches");
for (const rule of criterion.check.rules) {
  rule.rule = "@typescript-eslint/ban-ts-comment";
}
const file = path.join(os.tmpdir(), "harness-probe-repoint.json");
writeFileSync(file, JSON.stringify(config, null, 2));

let output = "";
