import { spawn } from "node:child_process";
import { existsSync, statSync } from "node:fs";
import os from "node:os";
import path from "node:path";

const root = process.cwd();
const probe = path.join(root, "src/domain/__harness_probe.ts");
const unique = "harness-prove-probe-" + process.pid;
const journal = path.join(os.tmpdir(), unique + ".json");
const env = {
  ...process.env,
  PROVE_LOCK_PATH: path.join(os.tmpdir(), unique + ".lock"),
  PROVE_JOURNAL_PATH: journal,
};

const child = spawn("node", ["scripts/prove-guardrails.mjs"], {
  cwd: root,
  env,
  stdio: ["ignore", "pipe", "pipe"],
});

const deadline = Date.now() + 60000;
let appeared = false;
while (!appeared && Date.now() < deadline) {
  if (existsSync(probe)) appeared = true;
  else await new Promise((resolve) => setTimeout(resolve, 20));
}

if (!appeared) {
  console.error("the probe file never appeared, the test proves nothing");
  process.exit(1);
}

child.kill("SIGKILL");
await new Promise((resolve) => child.on("close", resolve));

if (!existsSync(journal)) {
  console.error("the killed run left no journal, so no later run can repair the tree");
  process.exit(1);
}

const { readFileSync } = await import("node:fs");
const record = JSON.parse(readFileSync(journal, "utf8"));
const names = (record.pendingFiles ?? []).map((entry) => entry.path);
if (!names.includes(probe)) {
  console.error("the journal does not name the probe it wrote");
  process.exit(1);
}

if (statSync(journal).mtimeMs > statSync(probe).mtimeMs) {
  console.error("the journal was written after the probe, so a kill between the two leaves a probe no run repairs");
  process.exit(1);
}

console.log("the journal was written before the probe");

// The killed run left its probe behind. The script takes it away, because the
// tree must be as it was before the script ran.
const { rmSync } = await import("node:fs");
rmSync(probe, { force: true });
rmSync(journal, { force: true });

import { spawn } from "node:child_process";

const root = process.cwd();

const holder = spawn("node", ["scripts/prove-guardrails.mjs"], {
  cwd: root,
  stdio: ["ignore", "pipe", "pipe"],
});

await new Promise((resolve) => setTimeout(resolve, 2000));

const second = spawn("node", ["scripts/prove-guardrails.mjs"], {
  cwd: root,
  stdio: ["ignore", "pipe", "pipe"],
  env: { ...process.env, PROVE_LOCK_WAIT_MS: "3000" },
});
let output = "";
second.stdout.on("data", (chunk) => {
  output += chunk;
});
second.stderr.on("data", (chunk) => {
  output += chunk;
});
const code = await new Promise((resolve) => second.on("close", resolve));

holder.kill("SIGTERM");
await new Promise((resolve) => holder.on("close", resolve));

if (code === 0) {
  console.error("the second run was allowed to run beside the first");
  process.exit(1);
}
if (!output.includes("pid ")) {
  console.error("the refusal does not name the holder:\n" + output);
  process.exit(1);
}

console.log("the refusal names the holder");
